Fallback ARM Keccak option (#276)

* Run sha3_keccak4_f1600_alt on all ARM architectures

Previously it was incorrectly filtered out in the testing and
benchmarking code on architectures not supporting SHA-3 intrinsics,
but in fact it doesn't use them.

* Add placeholder Keccak variant based on compiled code

This is an initial placeholder non-lazy-rotation version of
Keccak, designed for microarchitectures where lazy rotations make
things worse instead of better (e.g. A-72). It's simply the result
of `gcc -O3 -mcpu=cortex-a72 -ffixed-x18 -c ...` on the following
C code, which is more or less the translation of the HOL Light
specification into C:

```

void sha3_keccak_f1600_alt2(uint64_t a[25],uint64_t rc[24])
{ register uint64_t i;

  register uint64_t A00 = a[0];
  register uint64_t A10 = a[1];
  register uint64_t A20 = a[2];
  register uint64_t A30 = a[3];
  register uint64_t A40 = a[4];
  register uint64_t A01 = a[5];
  register uint64_t A11 = a[6];
  register uint64_t A21 = a[7];
  register uint64_t A31 = a[8];
  register uint64_t A41 = a[9];
  register uint64_t A02 = a[10];
  register uint64_t A12 = a[11];
  register uint64_t A22 = a[12];
  register uint64_t A32 = a[13];
  register uint64_t A42 = a[14];
  register uint64_t A03 = a[15];
  register uint64_t A13 = a[16];
  register uint64_t A23 = a[17];
  register uint64_t A33 = a[18];
  register uint64_t A43 = a[19];
  register uint64_t A04 = a[20];
  register uint64_t A14 = a[21];
  register uint64_t A24 = a[22];
  register uint64_t A34 = a[23];
  register uint64_t A44 = a[24];

  for (i = 0; i <= 23; ++i)
   { uint64_t C0 = A00 ^ A01 ^ A02 ^ A03 ^ A04;
     uint64_t C1 = A10 ^ A11 ^ A12 ^ A13 ^ A14;
     uint64_t C2 = A20 ^ A21 ^ A22 ^ A23 ^ A24;
     uint64_t C3 = A30 ^ A31 ^ A32 ^ A33 ^ A34;
     uint64_t C4 = A40 ^ A41 ^ A42 ^ A43 ^ A44;
     uint64_t D0 = C4 ^ word_rol(C1,1);
     uint64_t D1 = C0 ^ word_rol(C2,1);
     uint64_t D2 = C1 ^ word_rol(C3,1);
     uint64_t D3 = C2 ^ word_rol(C4,1);
     uint64_t D4 = C3 ^ word_rol(C0,1);
     uint64_t At00 = A00 ^ D0;
     uint64_t At01 = A01 ^ D0;
     uint64_t At02 = A02 ^ D0;
     uint64_t At03 = A03 ^ D0;
     uint64_t At04 = A04 ^ D0;
     uint64_t At10 = A10 ^ D1;
     uint64_t At11 = A11 ^ D1;
     uint64_t At12 = A12 ^ D1;
     uint64_t At13 = A13 ^ D1;
     uint64_t At14 = A14 ^ D1;
     uint64_t At20 = A20 ^ D2;
     uint64_t At21 = A21 ^ D2;
     uint64_t At22 = A22 ^ D2;
     uint64_t At23 = A23 ^ D2;
     uint64_t At24 = A24 ^ D2;
     uint64_t At30 = A30 ^ D3;
     uint64_t At31 = A31 ^ D3;
     uint64_t At32 = A32 ^ D3;
     uint64_t At33 = A33 ^ D3;
     uint64_t At34 = A34 ^ D3;
     uint64_t At40 = A40 ^ D4;
     uint64_t At41 = A41 ^ D4;
     uint64_t At42 = A42 ^ D4;
     uint64_t At43 = A43 ^ D4;
     uint64_t At44 = A44 ^ D4;
     uint64_t B00 = At00;
     uint64_t B01 = word_rol(At30,28);
     uint64_t B02 = word_rol(At10,1);
     uint64_t B03 = word_rol(At40,27);
     uint64_t B04 = word_rol(At20,62);
     uint64_t B10 = word_rol(At11,44);
     uint64_t B11 = word_rol(At41,20);
     uint64_t B12 = word_rol(At21,6);
     uint64_t B13 = word_rol(At01,36);
     uint64_t B14 = word_rol(At31,55);
     uint64_t B20 = word_rol(At22,43);
     uint64_t B21 = word_rol(At02,3);
     uint64_t B22 = word_rol(At32,25);
     uint64_t B23 = word_rol(At12,10);
     uint64_t B24 = word_rol(At42,39);
     uint64_t B30 = word_rol(At33,21);
     uint64_t B31 = word_rol(At13,45);
     uint64_t B32 = word_rol(At43,8);
     uint64_t B33 = word_rol(At23,15);
     uint64_t B34 = word_rol(At03,41);
     uint64_t B40 = word_rol(At44,14);
     uint64_t B41 = word_rol(At24,61);
     uint64_t B42 = word_rol(At04,18);
     uint64_t B43 = word_rol(At34,56);
     uint64_t B44 = word_rol(At14,2);
     A00 = (B00 ^ (~B10 & B20)) ^ rc[i];
     A10 =  B10 ^ (~B20 & B30);
     A20 =  B20 ^ (~B30 & B40);
     A30 =  B30 ^ (~B40 & B00);
     A40 =  B40 ^ (~B00 & B10);
     A01 =  B01 ^ (~B11 & B21);
     A11 =  B11 ^ (~B21 & B31);
     A21 =  B21 ^ (~B31 & B41);
     A31 =  B31 ^ (~B41 & B01);
     A41 =  B41 ^ (~B01 & B11);
     A02 =  B02 ^ (~B12 & B22);
     A12 =  B12 ^ (~B22 & B32);
     A22 =  B22 ^ (~B32 & B42);
     A32 =  B32 ^ (~B42 & B02);
     A42 =  B42 ^ (~B02 & B12);
     A03 =  B03 ^ (~B13 & B23);
     A13 =  B13 ^ (~B23 & B33);
     A23 =  B23 ^ (~B33 & B43);
     A33 =  B33 ^ (~B43 & B03);
     A43 =  B43 ^ (~B03 & B13);
     A04 =  B04 ^ (~B14 & B24);
     A14 =  B14 ^ (~B24 & B34);
     A24 =  B24 ^ (~B34 & B44);
     A34 =  B34 ^ (~B44 & B04);
     A44 =  B44 ^ (~B04 & B14);
   }

  a[0]  =  A00;
  a[1]  =  A10;
  a[2]  =  A20;
  a[3]  =  A30;
  a[4]  =  A40;
  a[5]  =  A01;
  a[6]  =  A11;
  a[7]  =  A21;
  a[8]  =  A31;
  a[9]  =  A41;
  a[10] =  A02;
  a[11] =  A12;
  a[12] =  A22;
  a[13] =  A32;
  a[14] =  A42;
  a[15] =  A03;
  a[16] =  A13;
  a[17] =  A23;
  a[18] =  A33;
  a[19] =  A43;
  a[20] =  A04;
  a[21] =  A14;
  a[22] =  A24;
  a[23] =  A34;
  a[24] = A44;
}
```

* Add proof for compiler-generated fallback Keccak code

The proof is an easy adaptation of the proofs for the other variants.
Since the compiler mixes the register save/restore with the other
computation, it turned out easier just to prove a single correctness
theorem SHA3_KECCAK_F1600_ALT2_SUBROUTINE_CORRECT instead of the
usual separate proof for the "core".

* Fix up comment banner and x86 testing dummy for new Keccak function

* Add CFI annotations to new fallback Keccak code

A couple of these are done directly because they don't match the
expected form of the CFI macros (this is compiler-generated code,
so some stylistic aspects are a bit different).

* Add constant-time property of sha3_keccak_f1600_alt2

